import { describe, expect, it } from 'vitest'
import { appendDecls, formatDecls, parseDecls } from './definition'

const symbols = (text: string) => parseDecls(text).map((d) => d.symbol)

describe('parseDecls', () => {
  it('reads one symbol per line with an optional note, skipping comments and empty lines', () => {
    expect(parseDecls("# tokeny\nid   identifikátor\n\n'a b'  s medzerou\n'#' mriežka\nE'\n")).toEqual([
      { symbol: 'id', note: 'identifikátor', line: 2 },
      { symbol: 'a b', note: 's medzerou', line: 4 },
      { symbol: '#', note: 'mriežka', line: 5 },
      { symbol: "E'", note: '', line: 6 },
    ])
  })
})

describe('appendDecls', () => {
  it('appends symbols so they read back as themselves', () => {
    const added = ['a b', '#', "E'", '|', 'ε', 'x']
    expect(symbols(appendDecls('id\n', added))).toEqual(['id', ...added])
  })
})

describe('formatDecls', () => {
  it('keeps punctuation terminals and their notes', () => {
    const text = '(\n)\n{\n}\n,\n;\nid identifikátor\n'
    expect(formatDecls(text)).toBe('(\n)\n{\n}\n,\n;\nid  identifikátor\n')
  })

  it('keeps a comma inside a note as part of the note', () => {
    expect(formatDecls('id   identifikátor, napr. x\nnum\n')).toBe('id  identifikátor, napr. x\nnum\n')
  })

  it('is stable – formatting a formatted list changes nothing', () => {
    const once = formatDecls("x  a\nlong_name  b\n'a b'\n#  komentár\n")
    expect(formatDecls(once)).toBe(once)
  })

  it('converts a C enum body pasted from the code base', () => {
    const text = 'typedef enum {\n  IDENT, // identifikátor\n  DEF = 3,\n  /* blok */ LAST\n} token_t;\n'
    expect(formatDecls(text)).toBe('IDENT  identifikátor\nDEF\nLAST\n')
  })

  it('converts several enumerators on one line', () => {
    expect(formatDecls('A, B, C, // posledný má popis\n')).toBe('A\nB\nC  posledný má popis\n')
  })
})
